/**
 * 微前端沙箱探测（按渲染拓扑分派，框架无关）。
 *
 * 拓扑三分：
 * - 同文档（无沙箱 / qiankun / micro-app light DOM / 降级 iframe）：absolute 正确
 * - 真 shadow DOM（web component 沙箱 / micro-app shadowDOM 模式）：absolute 正确，
 *   由组件的 `getRootNode() instanceof ShadowRoot` 检测命中
 * - graft 型（wujie）：iframe 文档树 graft 进 shadowRoot 渲染，absolute 输出视口系
 *   坐标但包含块是 graft body → 错位；fixed 以最近视口为包含块，是唯一正确解
 *
 * 安全性论证：非 graft 拓扑下 absolute 与 fixed 坐标等价（包含块同为最近视口），
 * iframe realm 下默认 fixed 零副作用；跨域 iframe 下 self/top 仅引用比较，
 * 不读属性，无 SecurityError。
 *
 * 已知边界：
 * - fixed 元素祖先有 transform/filter 时包含块被劫持（宿主布局应避免；graft 下
 *   absolute 的 offsetParent 解析本就失效，错法不同而非新增错误）
 * - fixed 面板在祖先滚动时依赖 autoUpdate 重算，重算前一帧有视口驻留（瞬时视觉差异）
 * - 若未来出现「非 iframe 的 graft 型沙箱」，本探测无法覆盖，需追加该沙箱的 marker 信号
 */

/** 组件 JS 是否运行在 iframe realm（wujie / iframe 型沙箱 / 普通 iframe 嵌入） */
export function isInIframeRealm(): boolean {
  return typeof window !== "undefined" && window.self !== window.top;
}

/** 是否处于 wujie graft 沙箱（getRootNode/父链被 wujie patch 伪装，结构探测失效，
 *  依赖官方标记；wujie 在子应用脚本执行前注入，时序可靠） */
export function isInWujie(): boolean {
  return (
    typeof window !== "undefined" &&
    (window as { __POWERED_BY_WUJIE__?: boolean }).__POWERED_BY_WUJIE__ === true
  );
}

import { ref, type ComponentInternalInstance } from "vue";

export interface ConfirmPendingOptions {
  /** 当前组件实例：从 vnode 上取原始 onConfirm 监听器（emit 不回传返回值） */
  instance: ComponentInternalInstance | null;
  /** 无监听器时补发 confirm 事件 */
  emitConfirm: () => void;
  emitCancel: () => void;
  /** 关闭弹层（走受控桥） */
  close: () => void;
}

/**
 * 确认弹层公共 pending 语义：@confirm 处理器返回 Promise 时锁定关闭通道，
 * resolve 后自动关闭，reject 保持打开并退出 loading；同步处理器直接关闭。
 */
export function useConfirmPending(options: ConfirmPendingOptions) {
  const loading = ref(false);

  function handleConfirm() {
    if (loading.value) return;
    const handler = options.instance?.vnode.props?.onConfirm as
      | ((...args: unknown[]) => unknown)
      | undefined;
    const result = handler?.();
    if (!handler) options.emitConfirm();
    if (result instanceof Promise) {
      loading.value = true;
      result
        .then(() => {
          loading.value = false;
          options.close();
        })
        .catch(() => {
          loading.value = false;
        });
    } else {
      options.close();
    }
  }

  function handleCancel() {
    if (loading.value) return;
    options.emitCancel();
    options.close();
  }

  return { loading, handleConfirm, handleCancel };
}

import { computed, ref, type ComputedRef } from "vue";

export interface ControlledBooleanOptions {
  /** 受控值；返回 undefined 表示非受控（内部状态接管） */
  controlled: () => boolean | undefined;
  /** 非受控初始值 */
  defaultValue?: () => boolean;
  /** 状态变更对外同步（一般 emit("update:open", next)） */
  onChange?: (next: boolean) => void;
}

export interface ControlledBoolean {
  isOpen: ComputedRef<boolean>;
  setOpen: (next: boolean) => void;
}

/**
 * 业务组件惯例：Ark Root 恒走受控，非受控语义由内部 ref 实现。
 * `controlled()` 返回 undefined 时用内部值，否则永远跟随外部 prop。
 */
export function useControlledBoolean(options: ControlledBooleanOptions): ControlledBoolean {
  const internal = ref(options.defaultValue?.() ?? false);
  const isOpen = computed(() => options.controlled() ?? internal.value);

  function setOpen(next: boolean) {
    internal.value = next;
    options.onChange?.(next);
  }

  return { isOpen, setOpen };
}

import { computed, useId } from "vue";

/** 与 zag ids 兼容的宽类型：string 或函数型（如 select 的 item(value) => string） */
export type OverlayIds = Record<string, string | ((value: string) => string)>;

/**
 * 浮层组件 ids 全量覆盖（无冒号化）。
 *
 * 背景：zag 缺省 id 惯例形如 `popover:{scope.id}:title`（各包 *.dom.js get*Id
 * 兜底分支），而部分 part 元素并不总是渲染（title/description/anchor/clearTrigger/
 * arrow 等），machine 仍会按状态变更反复 getById 查询。wujie 沙箱把
 * document.getElementById patch 成 `querySelector('[id="…"]')` miss 后兜底
 * `querySelector('#'+id)`（wujie proxy.js），冒号未转义 → SyntaxError → catch 打出
 * "[wujie warn] 不支持document.getElementById()传入特殊字符…" 且打开期间反复刷屏。
 * ids 派生自 Vue useId()（v-0 格式，无冒号）后，未命中也是合法选择器，静默返回
 * null，告警消除；原生环境 getElementById 不解析选择器，行为零变化。
 *
 * 用法（组件 setup 内，inheritAttrs: false 透传模式下同样适用）：
 *   const { ids, resolveId } = useOverlayIds(attrs, {
 *     primary: "content",
 *     parts: ["title", "description", "anchor", "trigger", "closeTrigger", "positioner", "arrow"],
 *   });
 *   // 模板：<ArkXxx.Root v-bind="attrs" :ids="ids">（:ids 须位于 v-bind="attrs" 之后）
 *   // aria 手动接线取元素 id 时用 resolveId(part)（user 覆盖优先，与实际 DOM 一致）
 *
 * 边界：parts 只声明「字符串型覆盖口」的 part；函数型 part（如 select 的
 * item/itemGroup/itemGroupLabel——元素必渲染，[id="…"] 首查即命中，无炸点）不进
 * parts，由 user 经 attrs.ids 直传原样保留。user 永远最后展开：显式传入以其为准。
 */
export function useOverlayIds(
  attrs: Record<string, unknown>,
  options: { primary: string; parts: readonly string[] },
) {
  const stemId = useId();
  const userIds = computed(() => (attrs.ids ?? {}) as OverlayIds);
  /** 默认派生值（不含 user 覆盖），独立于 ids 供 resolveId 回退；构造恒为字符串 */
  const buildBase = (): Record<string, string> => {
    const base: Record<string, string> = {};
    for (const part of options.parts) {
      base[part] = part === options.primary ? stemId : `${stemId}-${part}`;
    }
    return base;
  };
  const ids = computed<OverlayIds>(() => ({ ...buildBase(), ...userIds.value })); // user 永远收尾
  /** aria 接线用：user 字符串覆盖优先，函数型 user 回退默认值 */
  const resolveId = (part: string) => {
    const v = userIds.value[part];
    return typeof v === "string" ? v : buildBase()[part];
  };
  return { ids, resolveId };
}

import type { ComputedRef } from "vue";
import { computed, getCurrentInstance, onMounted, ref } from "vue";
import { isInIframeRealm, isInWujie } from "./sandbox";

/**
 * 浮层沙箱适配公共层（Popover 0.5.3 修复的推广形态，机制与实测依据见 sandbox.ts 头注）：
 * - useSandboxTeleportTarget：Teleport 目标降级（真 shadow DOM / wujie graft → 应用挂载容器）
 * - withSandboxStrategy：iframe realm 下 positioning.strategy 默认 fixed（absolute 包含块错位修正）
 */

/**
 * 浮层 Teleport 目标解析：显式 to > shadow DOM / wujie graft 自动降级 > body。
 *
 * app._container 在 mount 的 render 完成后才赋值（runtime-core 3.5.43：render L4337
 * → 赋值 L4340），而子组件 onMounted 在 render 内同步执行、届时仍为 undefined，
 * 故检测再延后一个微任务（mount 调用栈结束后 _container 必已赋值），结果存 ref
 * 驱动 computed 重算；getCurrentInstance 仅 setup 同步上下文可用，本函数须在
 * setup 顶层调用。共享 Vue（__MICRO_SHARED__）下各子应用 app._container 相互
 * 独立，检测按实例隔离。
 * 沙箱两类：真 shadow DOM 由 getRootNode() 命中；wujie graft 下 getRootNode/父链
 * 被 patch 伪装成 iframe 文档语义（实测），结构探测失效，须叠加官方标记位。
 * 其余微前端（qiankun / micro-app light DOM）body 即主文档 body，兜底正确。
 *
 * @param explicitTo 组件显式 to 的取值函数（响应式安全：computed 内重读）
 * @returns Teleport 目标（显式 to 优先，其次降级容器，兜底 body）
 */
export function useSandboxTeleportTarget(
  explicitTo: () => string | HTMLElement | undefined,
): ComputedRef<string | HTMLElement> {
  const instance = getCurrentInstance();
  const inWujie = isInWujie();
  const detectedTarget = ref<string | HTMLElement>("body");
  onMounted(() => {
    queueMicrotask(() => {
      if (explicitTo()) return;
      const container = (instance?.appContext.app as { _container?: HTMLElement } | undefined)
        ?._container;
      if (container && (container.getRootNode() instanceof ShadowRoot || inWujie)) {
        detectedTarget.value = container;
      }
    });
  });
  return computed(() => explicitTo() ?? detectedTarget.value);
}

/**
 * iframe realm（wujie graft / iframe 型沙箱 / iframe 嵌入）且用户未显式指定
 * strategy 时默认 fixed：非 graft 拓扑下 fixed 与 absolute 坐标等价（零副作用），
 * graft 拓扑（wujie）absolute 包含块错位，fixed 是唯一正确解。
 * 纯函数、原地写入 merged（调用方传入自己的合成对象，无共享引用风险）；
 * user.strategy 显式给出（含 null 意义上的「未传」判定用 == null）时以其为准。
 *
 * @param user 用户原始 positioning（undefined 或经 attrs 透传的合成对象）
 * @param merged 组件已合成 placement/sameWidth 等的基础 positioning（将被写入）
 * @returns 写入 strategy 后的 merged（同引用，便于 computed 直接 return）
 */
export function withSandboxStrategy<T extends object>(user: T | undefined, merged: T): T {
  if (isInIframeRealm() && (user as { strategy?: string } | undefined)?.strategy == null) {
    (merged as { strategy?: string }).strategy = "fixed";
  }
  return merged;
}
